INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('article:COURSE-ONLINE-11','article','','Objaw i podzespoły','','body: Objaw i podzespoły Oddziel brak POST od usterki obrazu. Rozważ pamięć RAM, dysk, układ graficzny, panel i firmware dopiero w kontekście pozostałych wyników. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-12','article','','Test po naprawie','','body: Test po naprawie Powtórz test pierwotnego objawu, sprawdź funkcje urządzenia i zapisz wynik. Jeśli usterka powraca, diagnoza nie jest zakończona. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-13','article','','Jak czytać schemat i boardview','','body: Jak czytać schemat i boardview Zidentyfikuj kod płyty i rewizję, znajdź blok wejścia zasilania, a potem prześledź nazwy sieci, bezpieczniki, przetwornice i sygnały włączające. Boardview pokazuje położenie elementów, ale samo w sobie nie zastępuje schematu ani pomiaru. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-14','article','','Diagnostyka karty graficznej','','body: Diagnostyka karty graficznej Porównaj obraz z różnych wyjść, moment wystąpienia artefaktów, temperatury i zachowanie sterownika. W PC sprawdź osadzenie karty przy odłączonym zasilaniu. Analiza linii zasilania pamięci i rdzenia to praca dla technika. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-15','article','','Analiza BIOS/UEFI i pamięci SPI','','body: Analiza BIOS/UEFI i pamięci SPI Aktualizuj tylko pliki dla dokładnego modelu, z oficjalnej strony i przy stabilnym zasilaniu. Przed pracą z programatorem technik identyfikuje kość, jej napięcie i właściwy wsad oraz zachowuje kopię oryginalnej zawartości. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-16','article','','Wyposażenie serwisowe i granice pracy','','body: Wyposażenie serwisowe i granice pracy Multimetr, dokumentacja i ochrona ESD stanowią podstawę. Zasilacz laboratoryjny, oscyloskop, mikroskop, hot-air i programator wymagają umiejętności oraz procedur. Nie stosuj wstrzykiwania napięcia ani prób zwarciowych według ogólnej ilustracji. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-SECTION-37','article','','Bezpieczeństwo obowiązuje w każdym rozdziale','','body: Bezpieczeństwo obowiązuje w każdym rozdziale Przed otwarciem wyłącz urządzenie i odłącz zasilanie. Baterię wewnętrzną odłącz po uzyskaniu dostępu zgodnie z instrukcją modelu. Nie otwieraj zasilacza sieciowego ani pakietu baterii. Zalanie, dym, korozja, nadpalenie lub spuchnięta bateria: przerwij pracę i nie uruchamiaj sprzętu ponownie. Ciągłość i rezystancję mierzy się wyłącznie bez zasilania. Pomiary na odsłoniętej, zasilanej płycie, wstrzykiwanie napięcia, lutowanie oraz programowanie kości SPI pozostaw przygotowanemu technikowi. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-SECTION-38','article','','Znajdź objaw. Sprawdź kolejne kroki.','','body: BIBLIOTEKA USTEREK Znajdź objaw. Sprawdź kolejne kroki. Wyszukaj problem i rozwiń temat. To pierwsze kontrole, a nie gwarantowana diagnoza bez oględzin konkretnego urządzenia. Szukaj usterki Wyczyść Nie włącza się wcale Sprawdź gniazdko, zgodność ładowarki, stan przewodu i reakcję kontrolek. Odłącz akcesoria i zanotuj, czy urządzenie reaguje na przycisk. Jeśli zgodne zasilanie jest sprawne, a reakcji nie ma, przekaż diagnostykę toru wejściowego i sekwencji zasilania serwisowi. Uruchamia się, ale nie ma obrazu Sprawdź jasność i monitor zewnętrzny. Zapisz kody diod i sygnały dźwiękowe producenta. Wymienny RAM osadzaj ponownie wyłącznie po odłączeniu zasilania. Obraz na monitorze zewnętrznym kieruje uwagę na tor wyświetlania laptopa, ale nie dowodzi samodzielnie, że płyta główna jest całkowicie sprawna. Restartuje się lub przegrzewa Sprawdź drożność otworów wentylacyjnych, obciążenie i odczyty temperatur. Zapisz moment wyłączenia; nie powtarzaj długich testów obciążeniowych, jeśli komputer nagle gaśnie. Nietypowy hałas wentylatora lub naprawa chłodzenia wymagająca rozbiórki to powód, aby skorzystać z dokumentacji modelu albo serwisu. Działa wolno lub dysk zgłasza błędy Najpierw zabezpiecz ważne dane. Potem sprawdź wolne miejsce, obciążenie systemu i informacje SMART; pojedynczy poprawny odczyt nie wyklucza awarii. Klikający HDD, znikający dysk lub ważne dane na niestabilnym nośniku wymagają ostrożności. Unikaj wielokrotnych testów zapisu. Bateria nie ładuje Sprawdź moc i zgodność ładowarki, właściwy port oraz ustawienia limitu ładowania. W Windows raport baterii utworzysz poleceniem powercfg /batteryreport. Spuchniętej baterii nie ładuj ani nie otwieraj. Diagnostykę układu ładowania i komunikacji baterii pozostaw serwisowi. BIOS/UEFI lub rozruch nie działa Zanotuj komunikat, sprawdź, czy dysk jest wykrywany, i sfotografuj ustawienia. Przy szyfrowaniu zabezpiecz klucz odzyskiwania przed zmianą konfiguracji rozruchu. Nie wgrywaj przypadkowego pliku firmware ani nie zwieraj pinów. Procedura odzyskiwania musi pasować do dokładnego modelu i rewizji. Artefakty lub problem z GPU Zapisz, czy artefakty pojawiają się przed startem systemu czy dopiero w aplikacji. Sprawdź kabel, monitor, sterownik i temperatury bez przeciążania niestabilnego sprzętu. Naprawy BGA, podgrzewanie układu i prace przy zasilaniu GPU wymagają wyposażenia oraz diagnostyki serwisowej; „wygrzewanie” nie jest wiarygodną naprawą. Brak Wi-Fi lub internetu Sprawdź sieć na drugim urządzeniu, tryb samolotowy, Ethernet i sterownik. Ustal, czy problem dotyczy komputera, routera czy dostawcy. Jeśli karta nie jest wykrywana lub port jest fizycznie uszkodzony, potrzebna może być naprawa sprzętowa. Zalanie, korozja lub zapach spalenizny Wyłącz i odłącz zasilanie, jeżeli można to zrobić bezpiecznie. Nie sprawdzaj „czy jeszcze działa”, nie podłączaj ładowarki i nie susz gorącym powietrzem. Przekaż urządzenie serwisowi; podaj rodzaj cieczy, czas zdarzenia i informację, czy najważniejsze jest odzyskanie danych. Windows nie startuje lub pokazuje BSOD Zapisz kod błędu i ostatnią zmianę. Zabezpiecz dane i klucz BitLocker; następnie sprawdź narzędzia naprawy uruchamiania, sterowniki oraz stan dysku. Nie resetuj ani nie reinstaluj systemu na dysku z podejrzeniem awarii przed oceną możliwości odzyskania danych. Brak pasującego tematu. Spróbuj krótszego hasła, np. „ekran”, „dysk” albo „BIOS”. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-SECTION-39','article','','Tematy do obejrzenia krok po kroku','','body: UCZ SIĘ NA DEMONSTRACJACH Tematy do obejrzenia krok po kroku Odnośniki otwierają wyniki wyszukiwania filmów w nowej karcie — nie są osadzonymi odtwarzaczami ani rekomendacją konkretnego nagrania. Przed wykonaniem czynności porównaj film z dokumentacją swojego modelu. BHP i ochrona ESD — znajdź demonstracje ↗ Bezpieczny demontaż laptopa ↗ Multimetr: podstawy napięcia DC ↗ Brak obrazu: pierwsze testy ↗ Czytanie schematu i boardview ↗ Bezpieczna aktualizacja BIOS/UEFI ↗ source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-SECTION-40','article','','Lista kontroli po naprawie','','body: Lista kontroli po naprawie Potwierdź pierwotny objaw w tych samych warunkach. Sprawdź start systemu, obraz, klawiaturę, porty, sieć, ładowanie, wentylator i temperatury. Zamknij obudowę i zadbaj o kopię ważnych danych. Jeśli objaw powraca, zapisz dokładny model, wyniki testów i okoliczności wystąpienia usterki. Nie uznawaj naprawy za zakończoną. Oficjalna dokumentacja Instrukcję demontażu, kody diagnostyczne i firmware dobieraj dla dokładnego modelu. Pomoc producenta ma pierwszeństwo przed filmem pokazującym inny sprzęt. Pomoc techniczna Windows ↗ Dokumentacja Dell ↗ Dokumentacja Lenovo ↗ Dokumentacja HP ↗ source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:ARTICLE31-001','article','','Diagnostyka sekcji zasilania CPU (VRM)','CPU VRM power-stage diagnostics','body: Diagnostyka sekcji zasilania CPU (VRM) CEL I ZAKRES Analiza wejścia EPS, kontrolera PWM, faz zasilania, MOSFET-ów i cewek na podstawie schematu konkretnej płyty. OBJAWY PC wyłącza się pod obciążeniem, CPU nie osiąga deklarowanych zegarów lub płyta nie przechodzi POST. TOK ROZUMOWANIA Oddziel brak sygnału EN/PWRGOOD, ograniczenie termiczne, przeciążenie i problem firmware. Odczytaj logi i porównaj zachowanie na ustawieniach domyślnych. PLAN DZIAŁANIA 1. Potwierdź model, rewizję i wersję firmware. 2. Udokumentuj objaw oraz warunki jego wystąpienia. 3. Zabezpiecz dane i uzyskaj zgodę na testy. 4. Przygotuj stanowisko ESD i właściwe narzędzia. 5. Wykonuj pojedyncze testy, zapisując wynik oraz warunki. 6. Porównaj z dokumentacją producenta. 7. Dobierz naprawę po potwierdzeniu przyczyny. 8. Przeprowadź test końcowy i sporządź raport. ROZWIĄZANIA Naprawa ma wynikać z pomiarów kontrolera, przebiegu zasilania i oględzin elementów; wymieniaj tylko potwierdzony uszkodzony element. BEZPIECZEŃSTWO Nie wykonuj pomiarów po stronie sieciowej PSU. Pomiary na pracującej płycie wymagają kwalifikacji, sond zabezpieczonych i dokumentacji. KRYTERIUM ODBIORU Pierwotny objaw nie występuje w odtwarzalnym teście; funkcje powiązane z naprawą działają, a raport zawiera ograniczenia i wyniki. source: Akademia Serwisu PRO — ścieżka serwisowa 3.1.0','bodyEn: CPU VRM power-stage diagnostics SCOPE This article explains how to approach the topic using the exact device model and OEM documentation. DIAGNOSTIC WORKFLOW 1. Confirm the exact model, board revision and firmware. 2. Record symptoms and their reproduction conditions. 3. Protect customer data and obtain consent. 4. Prepare ESD-safe tools and the appropriate service manual. 5. Run controlled tests, changing one variable at a time. 6. Record measurements, log codes and reference sources. 7. Repair only after a repeatable test confirms the cause. 8. Repeat the original scenario and document PASS/FAIL. SAFETY Stop for smoke, liquid damage, a swollen battery, exposed mains voltage or an unidentified short. Never guess firmware or pinouts. ACCEPTANCE The original symptom is no longer reproducible, related functions pass and the report lists limitations.','','Akademia Serwisu PRO — ścieżka serwisowa 3.1.0'),
('article:ARTICLE31-002','article','','Diagnostyka braku obrazu z dedykowanej karty GPU','Dedicated GPU no-display diagnostics','body: Diagnostyka braku obrazu z dedykowanej karty GPU CEL I ZAKRES Oddziel usterkę karty, slotu PCIe, przewodu obrazu, monitora, firmware i sterownika. OBJAWY Wentylatory ruszają, ale monitor nie wykrywa sygnału; system może uruchamiać się w tle. TOK ROZUMOWANIA Sprawdź POST/debug LED, wyjście płyty, inny przewód i ekran oraz wykrycie urządzenia w systemie. PLAN DZIAŁANIA 1. Potwierdź model, rewizję i wersję firmware. 2. Udokumentuj objaw oraz warunki jego wystąpienia. 3. Zabezpiecz dane i uzyskaj zgodę na testy. 4. Przygotuj stanowisko ESD i właściwe narzędzia. 5. Wykonuj pojedyncze testy, zapisując wynik oraz warunki. 6. Porównaj z dokumentacją producenta. 7. Dobierz naprawę po potwierdzeniu przyczyny. 8. Przeprowadź test końcowy i sporządź raport. ROZWIĄZANIA Dopiero po izolacji przyczyny wykonaj kontrolę złącza, zasilania PCIe i test karty w zgodnym, sprawnym zestawie. BEZPIECZEŃSTWO Nie wkładaj i nie wyjmuj GPU przy zasilonym komputerze; nie dotykaj styków ani nie zwieraj pinów slotu. KRYTERIUM ODBIORU Pierwotny objaw nie występuje w odtwarzalnym teście; funkcje powiązane z naprawą działają, a raport zawiera ograniczenia i wyniki. source: Akademia Serwisu PRO — ścieżka serwisowa 3.1.0','bodyEn: Dedicated GPU no-display diagnostics SCOPE This article explains how to approach the topic using the exact device model and OEM documentation. DIAGNOSTIC WORKFLOW 1. Confirm the exact model, board revision and firmware. 2. Record symptoms and their reproduction conditions. 3. Protect customer data and obtain consent. 4. Prepare ESD-safe tools and the appropriate service manual. 5. Run controlled tests, changing one variable at a time. 6. Record measurements, log codes and reference sources. 7. Repair only after a repeatable test confirms the cause. 8. Repeat the original scenario and document PASS/FAIL. SAFETY Stop for smoke, liquid damage, a swollen battery, exposed mains voltage or an unidentified short. Never guess firmware or pinouts. ACCEPTANCE The original symptom is no longer reproducible, related functions pass and the report lists limitations.','','Akademia Serwisu PRO — ścieżka serwisowa 3.1.0'),
('article:ARTICLE31-003','article','','Artefakty obrazu i niestabilność pamięci VRAM','Display artifacts and VRAM instability','body: Artefakty obrazu i niestabilność pamięci VRAM CEL I ZAKRES Rozpoznawanie artefaktów zależnych od temperatury, obciążenia, sterownika i połączenia wyświetlacza. OBJAWY Kolorowe bloki, migotanie, błędy tekstur, reset sterownika lub czarny ekran. TOK ROZUMOWANIA Zapisz, czy artefakt występuje w BIOS, na pulpicie, w zrzucie ekranu i na innym monitorze. Porównaj temperatury oraz logi. PLAN DZIAŁANIA 1. Potwierdź model, rewizję i wersję firmware. 2. Udokumentuj objaw oraz warunki jego wystąpienia. 3. Zabezpiecz dane i uzyskaj zgodę na testy. 4. Przygotuj stanowisko ESD i właściwe narzędzia. 5. Wykonuj pojedyncze testy, zapisując wynik oraz warunki. 6. Porównaj z dokumentacją producenta. 7. Dobierz naprawę po potwierdzeniu przyczyny. 8. Przeprowadź test końcowy i sporządź raport. ROZWIĄZANIA Przyczynę potwierdź powtarzalnym testem; sterownik, przewód lub monitor wyklucz przed podejrzeniem VRAM. BEZPIECZEŃSTWO Nie używaj długich testów obciążeniowych przy artefaktach, przegrzewaniu lub zapachu spalenizny. KRYTERIUM ODBIORU Pierwotny objaw nie występuje w odtwarzalnym teście; funkcje powiązane z naprawą działają, a raport zawiera ograniczenia i wyniki. source: Akademia Serwisu PRO — ścieżka serwisowa 3.1.0','bodyEn: Display artifacts and VRAM instability SCOPE This article explains how to approach the topic using the exact device model and OEM documentation. DIAGNOSTIC WORKFLOW 1. Confirm the exact model, board revision and firmware. 2. Record symptoms and their reproduction conditions. 3. Protect customer data and obtain consent. 4. Prepare ESD-safe tools and the appropriate service manual. 5. Run controlled tests, changing one variable at a time. 6. Record measurements, log codes and reference sources. 7. Repair only after a repeatable test confirms the cause. 8. Repeat the original scenario and document PASS/FAIL. SAFETY Stop for smoke, liquid damage, a swollen battery, exposed mains voltage or an unidentified short. Never guess firmware or pinouts. ACCEPTANCE The original symptom is no longer reproducible, related functions pass and the report lists limitations.','','Akademia Serwisu PRO — ścieżka serwisowa 3.1.0'),
('article:ARTICLE31-004','article','','Odtwarzanie BIOS z funkcji Flashback','BIOS recovery using Flashback','body: Odtwarzanie BIOS z funkcji Flashback CEL I ZAKRES Przygotowanie zgodnego obrazu firmware, nośnika USB, nazwy pliku i sekwencji odzyskiwania według OEM. OBJAWY Płyta nie przechodzi POST po przerwanym update albo firmware nie uruchamia konfiguracji. TOK ROZUMOWANIA Ustal dokładny model i rewizję PCB; potwierdź, że dana płyta ma funkcję Flashback i sprawdź jej instrukcję. PLAN DZIAŁANIA 1. Potwierdź model, rewizję i wersję firmware. 2. Udokumentuj objaw oraz warunki jego wystąpienia. 3. Zabezpiecz dane i uzyskaj zgodę na testy. 4. Przygotuj stanowisko ESD i właściwe narzędzia. 5. Wykonuj pojedyncze testy, zapisując wynik oraz warunki. 6. Porównaj z dokumentacją producenta. 7. Dobierz naprawę po potwierdzeniu przyczyny. 8. Przeprowadź test końcowy i sporządź raport. ROZWIĄZANIA Użyj wyłącznie obrazu z oficjalnej strony dla dokładnej rewizji. Zachowaj stabilne zasilanie i nie przerywaj procesu. BEZPIECZEŃSTWO Nie flashuj obrazu z podobnego modelu. Nie odłączaj zasilania, gdy dioda wskazuje trwający zapis. KRYTERIUM ODBIORU Pierwotny objaw nie występuje w odtwarzalnym teście; funkcje powiązane z naprawą działają, a raport zawiera ograniczenia i wyniki. source: Akademia Serwisu PRO — ścieżka serwisowa 3.1.0','bodyEn: BIOS recovery using Flashback SCOPE This article explains how to approach the topic using the exact device model and OEM documentation. DIAGNOSTIC WORKFLOW 1. Confirm the exact model, board revision and firmware. 2. Record symptoms and their reproduction conditions. 3. Protect customer data and obtain consent. 4. Prepare ESD-safe tools and the appropriate service manual. 5. Run controlled tests, changing one variable at a time. 6. Record measurements, log codes and reference sources. 7. Repair only after a repeatable test confirms the cause. 8. Repeat the original scenario and document PASS/FAIL. SAFETY Stop for smoke, liquid damage, a swollen battery, exposed mains voltage or an unidentified short. Never guess firmware or pinouts. ACCEPTANCE The original symptom is no longer reproducible, related functions pass and the report lists limitations.','','Akademia Serwisu PRO — ścieżka serwisowa 3.1.0'),
('article:ARTICLE31-005','article','','Analiza ustawień UEFI i kolejności bootowania','UEFI settings and boot-order analysis','body: Analiza ustawień UEFI i kolejności bootowania CEL I ZAKRES Rozróżnianie UEFI/Legacy, GPT/MBR, Secure Boot, CSM, trybu kontrolera i wpisów boot managera. OBJAWY Komunikat no bootable device, zniknięcie wpisu Windows Boot Manager lub pętla firmware. TOK ROZUMOWANIA Zapisz ustawienia przed zmianą; sprawdź wykrywanie dysku i stan partycji bez modyfikowania danych. PLAN DZIAŁANIA 1. Potwierdź model, rewizję i wersję firmware. 2. Udokumentuj objaw oraz warunki jego wystąpienia. 3. Zabezpiecz dane i uzyskaj zgodę na testy. 4. Przygotuj stanowisko ESD i właściwe narzędzia. 5. Wykonuj pojedyncze testy, zapisując wynik oraz warunki. 6. Porównaj z dokumentacją producenta. 7. Dobierz naprawę po potwierdzeniu przyczyny. 8. Przeprowadź test końcowy i sporządź raport. ROZWIĄZANIA Przywracaj ustawienia pojedynczo i zgodnie z pierwotnym sposobem instalacji systemu. BEZPIECZEŃSTWO Nie przełączaj AHCI/RAID/VMD ani Secure Boot bez oceny wpływu na rozruch i klucze odzyskiwania. KRYTERIUM ODBIORU Pierwotny objaw nie występuje w odtwarzalnym teście; funkcje powiązane z naprawą działają, a raport zawiera ograniczenia i wyniki. source: Akademia Serwisu PRO — ścieżka serwisowa 3.1.0','bodyEn: UEFI settings and boot-order analysis SCOPE This article explains how to approach the topic using the exact device model and OEM documentation. DIAGNOSTIC WORKFLOW 1. Confirm the exact model, board revision and firmware. 2. Record symptoms and their reproduction conditions. 3. Protect customer data and obtain consent. 4. Prepare ESD-safe tools and the appropriate service manual. 5. Run controlled tests, changing one variable at a time. 6. Record measurements, log codes and reference sources. 7. Repair only after a repeatable test confirms the cause. 8. Repeat the original scenario and document PASS/FAIL. SAFETY Stop for smoke, liquid damage, a swollen battery, exposed mains voltage or an unidentified short. Never guess firmware or pinouts. ACCEPTANCE The original symptom is no longer reproducible, related functions pass and the report lists limitations.','','Akademia Serwisu PRO — ścieżka serwisowa 3.1.0'),
('article:ARTICLE31-006','article','','Diagnostyka TPM 2.0 i Secure Boot','TPM 2.0 and Secure Boot diagnostics','body: Diagnostyka TPM 2.0 i Secure Boot CEL I ZAKRES Weryfikacja stanu TPM, trybu Secure Boot, kluczy platformy i wymagań systemu. OBJAWY Windows zgłasza brak TPM, stan Secure Boot jest niepoprawny albo aplikacja nie spełnia wymagań. TOK ROZUMOWANIA Sprawdź `tpm.msc`, msinfo32 i dokumentację UEFI; rozróżnij TPM firmware, dTPM i ustawienia platformy. PLAN DZIAŁANIA 1. Potwierdź model, rewizję i wersję firmware. 2. Udokumentuj objaw oraz warunki jego wystąpienia. 3. Zabezpiecz dane i uzyskaj zgodę na testy. 4. Przygotuj stanowisko ESD i właściwe narzędzia. 5. Wykonuj pojedyncze testy, zapisując wynik oraz warunki. 6. Porównaj z dokumentacją producenta. 7. Dobierz naprawę po potwierdzeniu przyczyny. 8. Przeprowadź test końcowy i sporządź raport. ROZWIĄZANIA Ustawienia zmieniaj po kopii kluczy odzyskiwania BitLocker i sprawdzeniu wymagań producenta. BEZPIECZEŃSTWO Nie czyść TPM na urządzeniu użytkownika bez kopii kluczy i zgody — może to uniemożliwić dostęp do danych. KRYTERIUM ODBIORU Pierwotny objaw nie występuje w odtwarzalnym teście; funkcje powiązane z naprawą działają, a raport zawiera ograniczenia i wyniki. source: Akademia Serwisu PRO — ścieżka serwisowa 3.1.0','bodyEn: TPM 2.0 and Secure Boot diagnostics SCOPE This article explains how to approach the topic using the exact device model and OEM documentation. DIAGNOSTIC WORKFLOW 1. Confirm the exact model, board revision and firmware. 2. Record symptoms and their reproduction conditions. 3. Protect customer data and obtain consent. 4. Prepare ESD-safe tools and the appropriate service manual. 5. Run controlled tests, changing one variable at a time. 6. Record measurements, log codes and reference sources. 7. Repair only after a repeatable test confirms the cause. 8. Repeat the original scenario and document PASS/FAIL. SAFETY Stop for smoke, liquid damage, a swollen battery, exposed mains voltage or an unidentified short. Never guess firmware or pinouts. ACCEPTANCE The original symptom is no longer reproducible, related functions pass and the report lists limitations.','','Akademia Serwisu PRO — ścieżka serwisowa 3.1.0'),
('article:ARTICLE31-007','article','','Diagnostyka kontrolera EC/KBC','Embedded Controller (EC/KBC) diagnostics','body: Diagnostyka kontrolera EC/KBC CEL I ZAKRES Rozpoznawanie objawów związanych z kontrolerem klawiatury, przyciskiem Power, ładowaniem i sekwencją startową. OBJAWY Brak reakcji przycisku, nietypowe diody, brak ładowania lub nieregularny start. TOK ROZUMOWANIA Sprawdź złącza, przycisk, baterię, adapter i kody POST; odczyty linii EC wykonuj tylko według schematu. PLAN DZIAŁANIA 1. Potwierdź model, rewizję i wersję firmware. 2. Udokumentuj objaw oraz warunki jego wystąpienia. 3. Zabezpiecz dane i uzyskaj zgodę na testy. 4. Przygotuj stanowisko ESD i właściwe narzędzia. 5. Wykonuj pojedyncze testy, zapisując wynik oraz warunki. 6. Porównaj z dokumentacją producenta. 7. Dobierz naprawę po potwierdzeniu przyczyny. 8. Przeprowadź test końcowy i sporządź raport. ROZWIĄZANIA Weryfikuj firmware EC i procedurę producenta; programowanie układu powierz technikowi z właściwym sprzętem. BEZPIECZEŃSTWO Nie zwieraj pinów EC ani nie wgrywaj wsadu z innej rewizji płyty. KRYTERIUM ODBIORU Pierwotny objaw nie występuje w odtwarzalnym teście; funkcje powiązane z naprawą działają, a raport zawiera ograniczenia i wyniki. source: Akademia Serwisu PRO — ścieżka serwisowa 3.1.0','bodyEn: Embedded Controller (EC/KBC) diagnostics SCOPE This article explains how to approach the topic using the exact device model and OEM documentation. DIAGNOSTIC WORKFLOW 1. Confirm the exact model, board revision and firmware. 2. Record symptoms and their reproduction conditions. 3. Protect customer data and obtain consent. 4. Prepare ESD-safe tools and the appropriate service manual. 5. Run controlled tests, changing one variable at a time. 6. Record measurements, log codes and reference sources. 7. Repair only after a repeatable test confirms the cause. 8. Repeat the original scenario and document PASS/FAIL. SAFETY Stop for smoke, liquid damage, a swollen battery, exposed mains voltage or an unidentified short. Never guess firmware or pinouts. ACCEPTANCE The original symptom is no longer reproducible, related functions pass and the report lists limitations.','','Akademia Serwisu PRO — ścieżka serwisowa 3.1.0'),
('article:ARTICLE31-008','article','','Ocena kondycji baterii laptopa','Laptop battery health assessment','body: Ocena kondycji baterii laptopa CEL I ZAKRES Analiza pojemności projektowej i pełnego ładowania, cykli, napięcia, temperatury i komunikacji BMS. OBJAWY Krótki czas pracy, nagłe wyłączenie, brak ładowania lub komunikat o niewykrytej baterii. TOK ROZUMOWANIA Porównaj raport systemu z diagnostyką OEM, sprawdź zasilacz i zachowanie na zasilaniu sieciowym. PLAN DZIAŁANIA 1. Potwierdź model, rewizję i wersję firmware. 2. Udokumentuj objaw oraz warunki jego wystąpienia. 3. Zabezpiecz dane i uzyskaj zgodę na testy. 4. Przygotuj stanowisko ESD i właściwe narzędzia. 5. Wykonuj pojedyncze testy, zapisując wynik oraz warunki. 6. Porównaj z dokumentacją producenta. 7. Dobierz naprawę po potwierdzeniu przyczyny. 8. Przeprowadź test końcowy i sporządź raport. ROZWIĄZANIA Wymieniaj baterię tylko na zgodny, certyfikowany moduł; po wymianie wykonaj kalibrację, jeśli zaleca ją producent. BEZPIECZEŃSTWO Spuchniętej, przebitej lub przegrzewającej się baterii nie naciskaj, nie przebijaj ani nie ładuj. KRYTERIUM ODBIORU Pierwotny objaw nie występuje w odtwarzalnym teście; funkcje powiązane z naprawą działają, a raport zawiera ograniczenia i wyniki. source: Akademia Serwisu PRO — ścieżka serwisowa 3.1.0','bodyEn: Laptop battery health assessment SCOPE This article explains how to approach the topic using the exact device model and OEM documentation. DIAGNOSTIC WORKFLOW 1. Confirm the exact model, board revision and firmware. 2. Record symptoms and their reproduction conditions. 3. Protect customer data and obtain consent. 4. Prepare ESD-safe tools and the appropriate service manual. 5. Run controlled tests, changing one variable at a time. 6. Record measurements, log codes and reference sources. 7. Repair only after a repeatable test confirms the cause. 8. Repeat the original scenario and document PASS/FAIL. SAFETY Stop for smoke, liquid damage, a swollen battery, exposed mains voltage or an unidentified short. Never guess firmware or pinouts. ACCEPTANCE The original symptom is no longer reproducible, related functions pass and the report lists limitations.','','Akademia Serwisu PRO — ścieżka serwisowa 3.1.0'),
('article:ARTICLE31-009','article','','Analiza negocjacji USB-C Power Delivery','USB-C Power Delivery negotiation analysis','body: Analiza negocjacji USB-C Power Delivery CEL I ZAKRES Rozpoznawanie ról źródła i odbiornika, komunikatów CC, profili PDO i ograniczeń kabla/adaptera. OBJAWY Urządzenie ładuje się wolno, przerywa ładowanie lub działa tylko z wybranym adapterem. TOK ROZUMOWANIA Porównaj adapter, kabel e-marked, port i odbiornik; użyj miernika PD zgodnego ze specyfikacją. PLAN DZIAŁANIA 1. Potwierdź model, rewizję i wersję firmware. 2. Udokumentuj objaw oraz warunki jego wystąpienia. 3. Zabezpiecz dane i uzyskaj zgodę na testy. 4. Przygotuj stanowisko ESD i właściwe narzędzia. 5. Wykonuj pojedyncze testy, zapisując wynik oraz warunki. 6. Porównaj z dokumentacją producenta. 7. Dobierz naprawę po potwierdzeniu przyczyny. 8. Przeprowadź test końcowy i sporządź raport. ROZWIĄZANIA Wymień wyłącznie element potwierdzony testem; port i kontroler analizuj na schemacie dokładnej rewizji. BEZPIECZEŃSTWO Nie podawaj napięcia na nieznane piny ani nie używaj przypadkowych adapterów laboratoryjnych. KRYTERIUM ODBIORU Pierwotny objaw nie występuje w odtwarzalnym teście; funkcje powiązane z naprawą działają, a raport zawiera ograniczenia i wyniki. source: Akademia Serwisu PRO — ścieżka serwisowa 3.1.0','bodyEn: USB-C Power Delivery negotiation analysis SCOPE This article explains how to approach the topic using the exact device model and OEM documentation. DIAGNOSTIC WORKFLOW 1. Confirm the exact model, board revision and firmware. 2. Record symptoms and their reproduction conditions. 3. Protect customer data and obtain consent. 4. Prepare ESD-safe tools and the appropriate service manual. 5. Run controlled tests, changing one variable at a time. 6. Record measurements, log codes and reference sources. 7. Repair only after a repeatable test confirms the cause. 8. Repeat the original scenario and document PASS/FAIL. SAFETY Stop for smoke, liquid damage, a swollen battery, exposed mains voltage or an unidentified short. Never guess firmware or pinouts. ACCEPTANCE The original symptom is no longer reproducible, related functions pass and the report lists limitations.','','Akademia Serwisu PRO — ścieżka serwisowa 3.1.0'),
('article:ARTICLE31-010','article','','Diagnostyka Thunderbolt i stacji dokującej','Thunderbolt and docking-station diagnostics','body: Diagnostyka Thunderbolt i stacji dokującej CEL I ZAKRES Izolowanie problemów firmware, kabla, portu, autoryzacji, zasilania i zgodności urządzenia. OBJAWY Dock nie wykrywa monitorów, LAN, USB lub ładowania mimo podłączenia. TOK ROZUMOWANIA Sprawdź certyfikację i oznaczenia kabla, firmware docka, listę zgodności oraz zdarzenia systemowe. PLAN DZIAŁANIA 1. Potwierdź model, rewizję i wersję firmware. 2. Udokumentuj objaw oraz warunki jego wystąpienia. 3. Zabezpiecz dane i uzyskaj zgodę na testy. 4. Przygotuj stanowisko ESD i właściwe narzędzia. 5. Wykonuj pojedyncze testy, zapisując wynik oraz warunki. 6. Porównaj z dokumentacją producenta. 7. Dobierz naprawę po potwierdzeniu przyczyny. 8. Przeprowadź test końcowy i sporządź raport. ROZWIĄZANIA Testuj osobno monitor, zasilanie, USB i LAN; aktualizuj firmware wyłącznie według OEM. BEZPIECZEŃSTWO Nie wymuszaj niezgodnego trybu zasilania; aktualizacja docka może przerwać pracę wszystkich portów. KRYTERIUM ODBIORU Pierwotny objaw nie występuje w odtwarzalnym teście; funkcje powiązane z naprawą działają, a raport zawiera ograniczenia i wyniki. source: Akademia Serwisu PRO — ścieżka serwisowa 3.1.0','bodyEn: Thunderbolt and docking-station diagnostics SCOPE This article explains how to approach the topic using the exact device model and OEM documentation. DIAGNOSTIC WORKFLOW 1. Confirm the exact model, board revision and firmware. 2. Record symptoms and their reproduction conditions. 3. Protect customer data and obtain consent. 4. Prepare ESD-safe tools and the appropriate service manual. 5. Run controlled tests, changing one variable at a time. 6. Record measurements, log codes and reference sources. 7. Repair only after a repeatable test confirms the cause. 8. Repeat the original scenario and document PASS/FAIL. SAFETY Stop for smoke, liquid damage, a swollen battery, exposed mains voltage or an unidentified short. Never guess firmware or pinouts. ACCEPTANCE The original symptom is no longer reproducible, related functions pass and the report lists limitations.','','Akademia Serwisu PRO — ścieżka serwisowa 3.1.0'),
('article:ARTICLE311-001','article','','Dokumentowanie pomiarów w serwisie elektroniki','Documenting electronics service measurements','body: Dokumentowanie pomiarów w serwisie elektroniki ZAKRES I CEL Zapis pomiaru powinien obejmować model i rewizję płyty, punkt pomiarowy, wartość, jednostkę, stan urządzenia, obciążenie, przyrząd i źródło wartości odniesienia. Bez tych danych wynik nie jest porównywalny. KOLEJNOŚĆ PRACY 1. Ustal model, rewizję i zakres zgłoszenia. 2. Zabezpiecz dane i uzyskaj zgodę. 3. Przygotuj narzędzia i dokumentację OEM. 4. Wykonuj pojedyncze testy i zapisuj wyniki. 5. Porównaj z wartościami referencyjnymi. 6. Napraw dopiero po potwierdzeniu przyczyny. 7. Powtórz pierwotny scenariusz. 8. Wydaj raport PASS/FAIL. BEZPIECZEŃSTWO Nie podawaj wartości jako uniwersalnych. Porównuj tylko z dokumentacją właściwej rewizji. source: Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy','bodyEn: Documenting electronics service measurements SCOPE AND PURPOSE A service measurement record should include board model and revision, test point, value, unit, device state, load, instrument and reference source. Without this information, results are not comparable. WORKFLOW 1. Identify the exact model, revision and service scope. 2. Protect data and obtain authorization. 3. Prepare correct tools and OEM documentation. 4. Run one controlled test at a time and record results. 5. Compare against the correct reference values. 6. Repair only after confirming the cause. 7. Repeat the original failure scenario. 8. Issue a PASS/FAIL report. SAFETY Never present a value as universal. Compare only with documentation for the exact revision.','','Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy'),
('article:ARTICLE311-002','article','','Procedura diagnostyki po zalaniu laptopa','Laptop liquid-damage triage procedure','body: Procedura diagnostyki po zalaniu laptopa ZAKRES I CEL Po zalaniu nie uruchamiaj urządzenia „na próbę”. Odłącz zasilacz, bezpiecznie odizoluj baterię zgodnie z konstrukcją, udokumentuj ślady, ustal rodzaj cieczy i oceń obszary zagrożone korozją. KOLEJNOŚĆ PRACY 1. Ustal model, rewizję i zakres zgłoszenia. 2. Zabezpiecz dane i uzyskaj zgodę. 3. Przygotuj narzędzia i dokumentację OEM. 4. Wykonuj pojedyncze testy i zapisuj wyniki. 5. Porównaj z wartościami referencyjnymi. 6. Napraw dopiero po potwierdzeniu przyczyny. 7. Powtórz pierwotny scenariusz. 8. Wydaj raport PASS/FAIL. BEZPIECZEŃSTWO Ciecz i pozostałości mogą powodować zwarcia również po wyschnięciu. Praca wymaga procedury inspekcji i odpowiedniego sprzętu. source: Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy','bodyEn: Laptop liquid-damage triage procedure SCOPE AND PURPOSE After liquid ingress, do not power on the device “to check”. Disconnect the adapter, safely isolate the battery according to the design, document residue, identify the liquid and assess corrosion-prone areas. WORKFLOW 1. Identify the exact model, revision and service scope. 2. Protect data and obtain authorization. 3. Prepare correct tools and OEM documentation. 4. Run one controlled test at a time and record results. 5. Compare against the correct reference values. 6. Repair only after confirming the cause. 7. Repeat the original failure scenario. 8. Issue a PASS/FAIL report. SAFETY Liquid and residue may cause shorts even after drying. Inspection requires an approved procedure and suitable equipment.','','Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy'),
('article:ARTICLE311-003','article','','Porównanie SMART i NVMe Health Log','Comparing SMART and NVMe health logs','body: Porównanie SMART i NVMe Health Log ZAKRES I CEL SMART SATA i NVMe Health Information Log mają różne pola i semantykę. Odczytuj wartości natywne, uwzględniaj firmware i nie traktuj pojedynczego atrybutu jako wyroku o stanie dysku. KOLEJNOŚĆ PRACY 1. Ustal model, rewizję i zakres zgłoszenia. 2. Zabezpiecz dane i uzyskaj zgodę. 3. Przygotuj narzędzia i dokumentację OEM. 4. Wykonuj pojedyncze testy i zapisuj wyniki. 5. Porównaj z wartościami referencyjnymi. 6. Napraw dopiero po potwierdzeniu przyczyny. 7. Powtórz pierwotny scenariusz. 8. Wydaj raport PASS/FAIL. BEZPIECZEŃSTWO Przy błędach mediów i problemach mechanicznych ogranicz dalsze uruchomienia i zabezpiecz dane. source: Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy','bodyEn: Comparing SMART and NVMe health logs SCOPE AND PURPOSE SATA SMART and the NVMe Health Information Log use different fields and semantics. Read native values, consider firmware and never treat one attribute as a complete drive-health verdict. WORKFLOW 1. Identify the exact model, revision and service scope. 2. Protect data and obtain authorization. 3. Prepare correct tools and OEM documentation. 4. Run one controlled test at a time and record results. 5. Compare against the correct reference values. 6. Repair only after confirming the cause. 7. Repeat the original failure scenario. 8. Issue a PASS/FAIL report. SAFETY When media errors or mechanical symptoms appear, minimize further power cycles and protect data.','','Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy'),
('article:ARTICLE311-004','article','','Różnice między kopią plikową a obrazem sektorowym','File backup versus sector-by-sector imaging','body: Różnice między kopią plikową a obrazem sektorowym ZAKRES I CEL Kopia plikowa przenosi wybrane pliki i metadane. Obraz sektorowy może zachować struktury partycji, nieprzydzielone obszary i ślady systemu plików. Wybór zależy od celu odzyskiwania i kondycji nośnika. KOLEJNOŚĆ PRACY 1. Ustal model, rewizję i zakres zgłoszenia. 2. Zabezpiecz dane i uzyskaj zgodę. 3. Przygotuj narzędzia i dokumentację OEM. 4. Wykonuj pojedyncze testy i zapisuj wyniki. 5. Porównaj z wartościami referencyjnymi. 6. Napraw dopiero po potwierdzeniu przyczyny. 7. Powtórz pierwotny scenariusz. 8. Wydaj raport PASS/FAIL. BEZPIECZEŃSTWO Nie twórz obrazu na tym samym uszkodzonym nośniku. Zapisuj kopię na oddzielnym, sprawdzonym miejscu. source: Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy','bodyEn: File backup versus sector-by-sector imaging SCOPE AND PURPOSE A file backup copies selected files and metadata. A sector image can preserve partition structures, unallocated areas and filesystem remnants. The choice depends on recovery goals and drive health. WORKFLOW 1. Identify the exact model, revision and service scope. 2. Protect data and obtain authorization. 3. Prepare correct tools and OEM documentation. 4. Run one controlled test at a time and record results. 5. Compare against the correct reference values. 6. Repair only after confirming the cause. 7. Repeat the original failure scenario. 8. Issue a PASS/FAIL report. SAFETY Do not store an image on the failing source drive. Write it to separate verified storage.','','Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy'),
('article:ARTICLE311-005','article','','Metody weryfikacji obrazu ISO i firmware','Verifying ISO and firmware downloads','body: Metody weryfikacji obrazu ISO i firmware ZAKRES I CEL Pobieraj pliki z witryn producenta. Porównaj SHA-256, podpis cyfrowy i metadane wydania. Hash potwierdza zgodność z opublikowaną wartością, ale nie potwierdza sam w sobie wiarygodności źródła. KOLEJNOŚĆ PRACY 1. Ustal model, rewizję i zakres zgłoszenia. 2. Zabezpiecz dane i uzyskaj zgodę. 3. Przygotuj narzędzia i dokumentację OEM. 4. Wykonuj pojedyncze testy i zapisuj wyniki. 5. Porównaj z wartościami referencyjnymi. 6. Napraw dopiero po potwierdzeniu przyczyny. 7. Powtórz pierwotny scenariusz. 8. Wydaj raport PASS/FAIL. BEZPIECZEŃSTWO Nie uruchamiaj obrazu ani firmware, którego pochodzenia nie można potwierdzić. source: Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy','bodyEn: Verifying ISO and firmware downloads SCOPE AND PURPOSE Download files from vendor sites. Compare SHA-256, digital signature and release metadata. A hash confirms a match to the published value but does not by itself establish source trustworthiness. WORKFLOW 1. Identify the exact model, revision and service scope. 2. Protect data and obtain authorization. 3. Prepare correct tools and OEM documentation. 4. Run one controlled test at a time and record results. 5. Compare against the correct reference values. 6. Repair only after confirming the cause. 7. Repeat the original failure scenario. 8. Issue a PASS/FAIL report. SAFETY Do not run an image or firmware file whose provenance cannot be established.','','Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy'),
('article:ARTICLE311-006','article','','Plan testu obciążeniowego bez ryzyka dla klienta','A customer-safe stress-test plan','body: Plan testu obciążeniowego bez ryzyka dla klienta ZAKRES I CEL Test obciążeniowy powinien mieć cel, limity, czas, warunki przerwania i plan monitorowania. Najpierw sprawdź chłodzenie, zasilanie i stan dysku. Test nie może być pierwszą czynnością po zgłoszeniu awarii. KOLEJNOŚĆ PRACY 1. Ustal model, rewizję i zakres zgłoszenia. 2. Zabezpiecz dane i uzyskaj zgodę. 3. Przygotuj narzędzia i dokumentację OEM. 4. Wykonuj pojedyncze testy i zapisuj wyniki. 5. Porównaj z wartościami referencyjnymi. 6. Napraw dopiero po potwierdzeniu przyczyny. 7. Powtórz pierwotny scenariusz. 8. Wydaj raport PASS/FAIL. BEZPIECZEŃSTWO Przerwij przy artefaktach, zapachu, niestabilnym napięciu, temperaturze poza limitem lub nieoczekiwanym restarcie. source: Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy','bodyEn: A customer-safe stress-test plan SCOPE AND PURPOSE A stress test needs a purpose, limits, duration, stop conditions and monitoring plan. Check cooling, power and storage health first. Stress testing should not be the first action after a failure report. WORKFLOW 1. Identify the exact model, revision and service scope. 2. Protect data and obtain authorization. 3. Prepare correct tools and OEM documentation. 4. Run one controlled test at a time and record results. 5. Compare against the correct reference values. 6. Repair only after confirming the cause. 7. Repeat the original failure scenario. 8. Issue a PASS/FAIL report. SAFETY Stop for artifacts, smell, unstable power, out-of-limit temperatures or an unexpected reset.','','Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy'),
('article:ARTICLE311-007','article','','Protokół wydania komputera i ochrona prywatności','PC handover report and privacy protection','body: Protokół wydania komputera i ochrona prywatności ZAKRES I CEL Raport powinien opisywać zgłoszenie, diagnozę, wykonane czynności, części, testy PASS/FAIL, ograniczenia i zalecenia. Nie kopiuj haseł, kluczy BitLocker, plików klienta ani danych logowania do dokumentacji. KOLEJNOŚĆ PRACY 1. Ustal model, rewizję i zakres zgłoszenia. 2. Zabezpiecz dane i uzyskaj zgodę. 3. Przygotuj narzędzia i dokumentację OEM. 4. Wykonuj pojedyncze testy i zapisuj wyniki. 5. Porównaj z wartościami referencyjnymi. 6. Napraw dopiero po potwierdzeniu przyczyny. 7. Powtórz pierwotny scenariusz. 8. Wydaj raport PASS/FAIL. BEZPIECZEŃSTWO Przechowuj raport zgodnie z polityką retencji i dostępem do danych. source: Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy','bodyEn: PC handover report and privacy protection SCOPE AND PURPOSE A report should describe the complaint, diagnosis, work performed, parts, PASS/FAIL tests, limitations and recommendations. Never copy passwords, BitLocker keys, customer files or credentials into documentation. WORKFLOW 1. Identify the exact model, revision and service scope. 2. Protect data and obtain authorization. 3. Prepare correct tools and OEM documentation. 4. Run one controlled test at a time and record results. 5. Compare against the correct reference values. 6. Repair only after confirming the cause. 7. Repeat the original failure scenario. 8. Issue a PASS/FAIL report. SAFETY Store reports according to retention and access-control policies.','','Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy'),
('article:ARTICLE311-008','article','','Diagnostyka przegrzewania złącza i przewodu','Connector and cable overheating diagnostics','body: Diagnostyka przegrzewania złącza i przewodu ZAKRES I CEL Przebarwienie, zapach, wysoka temperatura lub stopienie obudowy złącza to sygnały do przerwania testów. Sprawdź zgodność przewodu, osadzenie, prąd i wymagania producenta. KOLEJNOŚĆ PRACY 1. Ustal model, rewizję i zakres zgłoszenia. 2. Zabezpiecz dane i uzyskaj zgodę. 3. Przygotuj narzędzia i dokumentację OEM. 4. Wykonuj pojedyncze testy i zapisuj wyniki. 5. Porównaj z wartościami referencyjnymi. 6. Napraw dopiero po potwierdzeniu przyczyny. 7. Powtórz pierwotny scenariusz. 8. Wydaj raport PASS/FAIL. BEZPIECZEŃSTWO Nie powtarzaj testu pod obciążeniem, dopóki przyczyna przegrzewania nie zostanie ustalona. source: Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy','bodyEn: Connector and cable overheating diagnostics SCOPE AND PURPOSE Discolouration, smell, high temperature or melted connector housing are stop-work indicators. Verify cable compatibility, seating, current and manufacturer requirements. WORKFLOW 1. Identify the exact model, revision and service scope. 2. Protect data and obtain authorization. 3. Prepare correct tools and OEM documentation. 4. Run one controlled test at a time and record results. 5. Compare against the correct reference values. 6. Repair only after confirming the cause. 7. Repeat the original failure scenario. 8. Issue a PASS/FAIL report. SAFETY Do not repeat a loaded test until the cause of overheating has been identified.','','Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy'),
('article:ARTICLE311-009','article','','Ocena jakości obrazu i artefaktów na monitorze','Display image-quality and artifact assessment','body: Ocena jakości obrazu i artefaktów na monitorze ZAKRES I CEL Zapisz rozdzielczość, odświeżanie, głębię koloru, HDR, kabel, wejście i źródło. Rozróżnij uszkodzenie panelu, artefakty GPU, problem EDID i zakłócenia połączenia. KOLEJNOŚĆ PRACY 1. Ustal model, rewizję i zakres zgłoszenia. 2. Zabezpiecz dane i uzyskaj zgodę. 3. Przygotuj narzędzia i dokumentację OEM. 4. Wykonuj pojedyncze testy i zapisuj wyniki. 5. Porównaj z wartościami referencyjnymi. 6. Napraw dopiero po potwierdzeniu przyczyny. 7. Powtórz pierwotny scenariusz. 8. Wydaj raport PASS/FAIL. BEZPIECZEŃSTWO Porównuj z innym źródłem i kablem zgodnym ze standardem; nie wymuszaj trybów poza specyfikacją. source: Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy','bodyEn: Display image-quality and artifact assessment SCOPE AND PURPOSE Record resolution, refresh rate, colour depth, HDR, cable, input and source. Distinguish panel failure, GPU artifacts, EDID issues and link integrity problems. WORKFLOW 1. Identify the exact model, revision and service scope. 2. Protect data and obtain authorization. 3. Prepare correct tools and OEM documentation. 4. Run one controlled test at a time and record results. 5. Compare against the correct reference values. 6. Repair only after confirming the cause. 7. Repeat the original failure scenario. 8. Issue a PASS/FAIL report. SAFETY Compare another source and standards-compliant cable; do not force modes outside specification.','','Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy'),
('article:ARTICLE311-010','article','','Procedura walidacji naprawy sieci Wi-Fi i routera','Wi-Fi and router repair validation','body: Procedura walidacji naprawy sieci Wi-Fi i routera ZAKRES I CEL Po zmianach sprawdź zasięg, roaming, DHCP, DNS, szyfrowanie, aktualność firmware i dostęp z urządzenia referencyjnego. Zmiany administracyjne muszą być zatwierdzone przez właściciela sieci. KOLEJNOŚĆ PRACY 1. Ustal model, rewizję i zakres zgłoszenia. 2. Zabezpiecz dane i uzyskaj zgodę. 3. Przygotuj narzędzia i dokumentację OEM. 4. Wykonuj pojedyncze testy i zapisuj wyniki. 5. Porównaj z wartościami referencyjnymi. 6. Napraw dopiero po potwierdzeniu przyczyny. 7. Powtórz pierwotny scenariusz. 8. Wydaj raport PASS/FAIL. BEZPIECZEŃSTWO Nie skanuj obcych sieci i nie zmieniaj haseł bez upoważnienia. source: Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy','bodyEn: Wi-Fi and router repair validation SCOPE AND PURPOSE After changes, verify coverage, roaming, DHCP, DNS, encryption, firmware status and access from a reference device. Administrative changes must be authorized by the network owner. WORKFLOW 1. Identify the exact model, revision and service scope. 2. Protect data and obtain authorization. 3. Prepare correct tools and OEM documentation. 4. Run one controlled test at a time and record results. 5. Compare against the correct reference values. 6. Repair only after confirming the cause. 7. Repeat the original failure scenario. 8. Issue a PASS/FAIL report. SAFETY Do not scan third-party networks or change passwords without authorization.','','Akademia Serwisu PRO 3.1.1 — materiał szkoleniowy'),
('article:ARTICLE320-001','article','','Zasady diagnostyki dysku z danymi klienta','Diagnosing a drive containing customer data','body: Zasady diagnostyki dysku z danymi klienta ZAKRES Nośnik może być sprawny elektrycznie, ale mieć błędy logiczne, zużyte komórki, uszkodzone sektory lub awarię kontrolera. Pierwszą decyzją nie jest „naprawa”, lecz ocena ryzyka dla danych. TOK DIAGNOSTYCZNY Odczyt SMART bez zapisu, identyfikacja szyfrowania, sprawdzenie kopii i wykonanie obrazu przed naprawą systemu plików. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Diagnosing a drive containing customer data SCOPE A drive can be electrically detected yet have logical errors, worn cells, bad sectors or a controller fault. The first decision is not “repair” but data-risk assessment. DIAGNOSTIC METHOD Read SMART without writing, identify encryption, check backups and image the media before filesystem repair. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-002','article','','Pełna procedura braku POST na komputerze stacjonarnym','Complete no-POST workflow for a desktop PC','body: Pełna procedura braku POST na komputerze stacjonarnym ZAKRES Brak POST może pochodzić z zasilania, CPU, pamięci, firmware, płyty, GPU lub urządzeń zewnętrznych. Wentylator obracający się nie dowodzi zakończonego POST. TOK DIAGNOSTYCZNY Zapis kodów diagnostycznych, minimalna konfiguracja zgodna z instrukcją, test RAM w zalecanym slocie, kontrola złączy EPS/ATX i porównanie na znanych sprawnych częściach. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Complete no-POST workflow for a desktop PC SCOPE No POST can originate from power, CPU, memory, firmware, board, GPU or external devices. A spinning fan does not prove POST completion. DIAGNOSTIC METHOD Record diagnostic codes, use a documented minimal configuration, test RAM in recommended slots, inspect EPS/ATX connectors and compare with known-good parts. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-003','article','','Proces kontroli złącza USB-C po uszkodzeniu mechanicznym','Inspecting a mechanically damaged USB-C port','body: Proces kontroli złącza USB-C po uszkodzeniu mechanicznym ZAKRES Złącze USB-C ma gęsto rozmieszczone kontakty. Odkształcenie może powodować zwarcie, przegrzewanie lub sporadyczne rozłączanie. TOK DIAGNOSTYCZNY Ocena wizualna przy powiększeniu, test kabla referencyjnego, pomiar zgodny z dokumentacją i ewentualna wymiana portu przez technika z odpowiednim stanowiskiem. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Inspecting a mechanically damaged USB-C port SCOPE USB-C connectors have densely spaced contacts. Deformation can cause shorts, overheating or intermittent disconnects. DIAGNOSTIC METHOD Magnified visual inspection, reference-cable test, measurements per documentation and possible port replacement by a technician with suitable equipment. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-004','article','','Diagnostyka niestabilnego RAM bez wymiany na ślepo','Diagnosing unstable RAM without blind replacement','body: Diagnostyka niestabilnego RAM bez wymiany na ślepo ZAKRES Błędy pamięci mogą wynikać z modułu, slotu, ustawień, kontrolera w CPU lub problemu płyty. Wymiana RAM bez odtworzenia testu nie jest diagnozą. TOK DIAGNOSTYCZNY Test modułów pojedynczo, ustawienia JEDEC, sloty według manuala, logi WHEA i porównanie wyników tej samej konfiguracji. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Diagnosing unstable RAM without blind replacement SCOPE Memory errors may arise from a module, slot, settings, CPU controller or board issue. Replacing RAM without reproducing the test is not a diagnosis. DIAGNOSTIC METHOD Test modules individually, use JEDEC settings, follow manual slot guidance, review WHEA logs and compare identical configurations. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta'),
('article:ARTICLE320-005','article','','Szczegółowa ocena przegrzewania laptopa','Detailed laptop overheating assessment','body: Szczegółowa ocena przegrzewania laptopa ZAKRES Wysoka temperatura może wynikać z zatkanego radiatora, słabego kontaktu termicznego, wentylatora, profilu mocy lub obciążenia programowego. TOK DIAGNOSTYCZNY Porównanie temperatury spoczynkowej i pod obciążeniem, obroty, drożność radiatora, docisk chłodzenia i logi throttlingu. STANDARDOWA KOLEJNOŚĆ 1. Identyfikacja modelu i rewizji. 2. Zapis objawu i historii. 3. Zabezpieczenie danych oraz zgoda. 4. Dokumentacja producenta i test bazowy. 5. Izolowanie jednej hipotezy naraz. 6. Działanie po potwierdzeniu przyczyny. 7. Test końcowy w tych samych warunkach. 8. Raport PASS/FAIL i ograniczenia. WAŻNE Wynik narzędzia nie jest automatycznie diagnozą. Zapisz warunki, wersje, źródła odniesienia oraz to, czego nie udało się przetestować. source: Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta','bodyEn: Detailed laptop overheating assessment SCOPE High temperatures can arise from a blocked heatsink, poor thermal contact, fan, power profile or software workload. DIAGNOSTIC METHOD Compare idle/load temperatures, RPM, heatsink airflow, cooler mounting and throttling logs. STANDARD WORKFLOW 1. Identify model and revision. 2. Record symptom and history. 3. Protect data and obtain consent. 4. Check OEM documentation and baseline test. 5. Isolate one hypothesis at a time. 6. Act only after confirming the cause. 7. Run final test under the same conditions. 8. Issue a PASS/FAIL report with limitations. IMPORTANT A tool result is not automatically a diagnosis. Record conditions, versions, reference sources and anything that could not be tested.','','Akademia Serwisu PRO 3.2.0 — materiał redakcyjny z odwołaniem do dokumentacji producenta');
